<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';$rows=$pdo->query("SELECT r.item_name,c.name category,r.location,h.handed_over_at FROM handover_records h JOIN claim_requests q ON q.id=h.claim_id JOIN item_reports r ON r.id=q.item_report_id JOIN categories c ON c.id=r.category_id WHERE q.status='returned' AND r.status='returned' ORDER BY h.handed_over_at DESC LIMIT 100")->fetchAll();$pageTitle='Returned items history';require __DIR__.'/../includes/header.php';?><h1>Returned items history</h1><p>This public list only shows items whose physical handover was confirmed. Claimant names and private evidence are not displayed.</p><div class="cards"><?php if(!$rows):?><div class="empty">No returned items to display yet.</div><?php else:foreach($rows as $r):?><article class="item-card"><span class="pill returned">Returned</span><h3><?=e($r['item_name'])?></h3><p><?=e($r['category'])?> · <?=e($r['location'])?></p><small>Returned <?=e($r['handed_over_at'])?></small></article><?php endforeach;endif;?></div><?php require __DIR__.'/../includes/footer.php';?>
